import type { Email } from "./send";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function layout(title: string, body: string): string {
  return `<!doctype html>
<html>
  <body style="margin:0;padding:24px;background:#f6f6f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;color:#111">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;margin:0 auto;background:#fff;border-radius:8px;padding:32px">
      <tr><td>
        <h1 style="margin:0 0 16px;font-size:20px">${escapeHtml(title)}</h1>
        ${body}
        <p style="margin:32px 0 0;font-size:12px;color:#888">— The Notely team</p>
      </td></tr>
    </table>
  </body>
</html>`;
}

function button(href: string, label: string): string {
  return `<p style="margin:24px 0"><a href="${escapeHtml(href)}" style="display:inline-block;background:#111;color:#fff;text-decoration:none;padding:10px 18px;border-radius:6px;font-size:14px">${escapeHtml(label)}</a></p>`;
}

export function welcomeEmail(params: { to: string; name: string; appUrl: string }): Email {
  const { to, name, appUrl } = params;
  const dashboardUrl = `${appUrl}/dashboard`;
  return {
    to,
    subject: "Welcome to Notely",
    html: layout(
      `Welcome, ${name}!`,
      `<p style="font-size:14px;line-height:1.5">Thanks for joining Notely. Your account is ready — jump in and write your first note.</p>
       ${button(dashboardUrl, "Open Notely")}`,
    ),
    text: `Welcome, ${name}!\n\nThanks for joining Notely. Your account is ready.\n\nOpen Notely: ${dashboardUrl}\n\n— The Notely team`,
  };
}

export function passwordResetEmail(params: {
  to: string;
  name: string;
  resetUrl: string;
  expiresInMinutes: number;
}): Email {
  const { to, name, resetUrl, expiresInMinutes } = params;
  return {
    to,
    subject: "Reset your Notely password",
    html: layout(
      "Reset your password",
      `<p style="font-size:14px;line-height:1.5">Hi ${escapeHtml(name)}, we received a request to reset your Notely password. This link expires in ${expiresInMinutes} minutes.</p>
       ${button(resetUrl, "Reset password")}
       <p style="font-size:12px;line-height:1.5;color:#666">If you didn't request this, you can safely ignore this email — your password won't change.</p>`,
    ),
    text: `Hi ${name},\n\nWe received a request to reset your Notely password. This link expires in ${expiresInMinutes} minutes:\n\n${resetUrl}\n\nIf you didn't request this, you can ignore this email.\n\n— The Notely team`,
  };
}
